code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Locate the horizontal three-cell color key.
    key = None
    for r in range(h):
        for c in range(w - 2):
            if all(grid[r][c + k] != 0 for k in range(3)):
                key = (r, c, [grid[r][c + k] for k in range(3)])
                break
        if key:
            break
    if key is None:
        return out

    kr, kc, colors = key
    key_cells = {(kr, kc + i): color for i, color in enumerate(colors)}
    # Extend each key color vertically; matching isolated marks set the stopping row.
    for i, color in enumerate(colors):
        col = kc + i
        marks = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color and (r, c) not in key_cells]
        stop = min((r for r, c in marks if r > kr), default=h - 1)
        for r in range(kr, stop + 1):
            out[r][col] = color
        # Connect each matching mark horizontally to the key column.
        for r, c in marks:
            if r != kr:
                for cc in range(min(c, col), max(c, col) + 1):
                    out[r][cc] = color
    return out
'''
